#pragma once

#include <cstdint>

// AI: below section was generated by an AI
constexpr uint16_t PALETTE_SERIAL_SAMPLE_COUNT = 256;
constexpr uint8_t PALETTE_SERIAL_RGB_CHUNK_SIZE = 8;
constexpr uint8_t PALETTE_SERIAL_STOP_CHUNK_SIZE = 4;
constexpr uint8_t PALETTE_SERIAL_RUNTIME_SLOT_COUNT = 16;

enum PaletteSerialLookupMode : uint8_t {
  PaletteLookupNoBlend,
  PaletteLookupLinearWrap,
  PaletteLookupLinearNoWrap,
};

struct PaletteSerialDumpPlan {
  uint8_t lookupCount = 0;
  PaletteSerialLookupMode lookupModes[2] = {
      PaletteLookupNoBlend,
      PaletteLookupNoBlend,
  };
  uint16_t slotChunks = 0;
  uint16_t stopChunks = 0;
  uint16_t lookupChunks = 0;
  uint16_t dataParts = 0;
};

constexpr uint16_t paletteSerialChunkCount(uint16_t itemCount, uint8_t chunkSize) {
  return itemCount ? (itemCount + chunkSize - 1U) / chunkSize : 0;
}

// WLED policy zero selects wrap or no-wrap per lookup call, so both tables are
// required to describe its complete active behavior without guessing how an effect calls it.
inline uint8_t paletteSerialLookupModes(
    uint8_t blendPolicy,
    PaletteSerialLookupMode (&modes)[2]
) {
  switch (blendPolicy) {
    case 0:
      modes[0] = PaletteLookupLinearWrap;
      modes[1] = PaletteLookupLinearNoWrap;
      return 2;
    case 1:
      modes[0] = PaletteLookupLinearWrap;
      return 1;
    case 2:
      modes[0] = PaletteLookupLinearNoWrap;
      return 1;
    case 3:
      modes[0] = PaletteLookupNoBlend;
      return 1;
    default:
      return 0;
  }
}

// Plans bounded serial records from declared counts. Stop count remains variable;
// the current firmware's retained-stop limit is not part of this response contract.
inline PaletteSerialDumpPlan makePaletteSerialDumpPlan(
    uint16_t sourceStopCount,
    uint8_t blendPolicy
) {
  PaletteSerialDumpPlan plan;
  plan.lookupCount = paletteSerialLookupModes(blendPolicy, plan.lookupModes);
  plan.slotChunks = paletteSerialChunkCount(
      PALETTE_SERIAL_RUNTIME_SLOT_COUNT, PALETTE_SERIAL_RGB_CHUNK_SIZE);
  plan.stopChunks = paletteSerialChunkCount(
      sourceStopCount, PALETTE_SERIAL_STOP_CHUNK_SIZE);
  plan.lookupChunks = paletteSerialChunkCount(
      PALETTE_SERIAL_SAMPLE_COUNT, PALETTE_SERIAL_RGB_CHUNK_SIZE);
  plan.dataParts = plan.slotChunks
      + plan.stopChunks
      + uint16_t(plan.lookupCount) * plan.lookupChunks;
  return plan;
}
